*** Update File: /home/czp/openvela_contest/.worktrees/bk7258-psram/chips/bk7258/Kconfig
@@
 config BK7258_TIMER0
 	bool "BK7258 Timer0 lower-half"
@@
 		Register the CP-owned BK7258 Timer0 channel as the standard NuttX
 		/dev/timer0 lower-half. Timer0 is a shared SoC resource and must not
 		be enabled independently by the AP image.
+
+config BK7258_PSRAM
+	bool "Initialize DevKit PSRAM as an additional heap"
+	depends on BK7258_COMPONENT_CP && MM_REGIONS > 1
+	default y
+	help
+		Initialize the PSRAM fitted to the BK7258 DevKit and add the detected
+		memory window to the ordinary NuttX user heap as a second region.
+
+		The driver probes only the APS6408L (8 MiB) and APS128XXO-OB9 (16 MiB)
+		command sequences verified in the Armino BK7258 CP implementation. It
+		uses internal SRAM until PSRAM initialization and a mapped-memory probe
+		succeed. A missing, unsupported, or failing device leaves the system
+		running on its internal-SRAM heap.
+
+		PSRAM is data heap only: it is not used for startup, linker sections,
+		stacks, DMA buffers, executable code, RPMsg, or shared-memory regions.
+
+config BK7258_PSRAM_PROBE_SIZE
+	int "PSRAM mapped-memory probe size"
+	depends on BK7258_PSRAM
+	default 10240
+	range 64 65536
+	help
+		Number of bytes tested at the beginning of the mapped PSRAM window
+		before that window is exposed to the NuttX allocator. The probe checks
+		word access and three distinct data patterns, then restores its saved
+		contents.
*** Update File: /home/czp/openvela_contest/.worktrees/bk7258-psram/chips/bk7258/include/bk7258_memorymap.h
@@
 #define BK7258_SRAM_CAPACITY_END  (BK7258_SRAM_CAPACITY_BASE + \
                                    BK7258_SRAM_CAPACITY_SIZE)
+
+/* External PSRAM is a CPU-visible data window. The controller can map up to
+ * 64 MiB, but the fitted-device size is discovered by the PSRAM driver before
+ * any portion is offered to the allocator. */
+
+#define BK7258_PSRAM_BASE          UINT32_C(0x60000000)
+#define BK7258_PSRAM_WINDOW_SIZE   UINT32_C(0x04000000)
@@
