+static int bk7258_psram_wait(uint32_t busy)
+{
+  unsigned int i;
+
+  for (i = 0; i < BK7258_PSRAM_COMMAND_LIMIT; i++)
+    {
+      if ((getreg32(BK7258_PSRAM_REG8) & busy) == 0)
+        {
+          return OK;
+        }
+    }
