+static void bk7258_psram_clock_120mhz(void)
+{
+  /* Armino's recommended default: 480 MHz source divided by four. */
+
+  modifyreg32(BK7258_SYS_CLKDIV2, 0,
+              BK7258_SYS_CLKDIV2_PSRAM_SEL |
+              BK7258_SYS_CLKDIV2_PSRAM_DIV);
